# nomes (CATIA V5, SOLIDWORKS, Inventor, Fenkra), status Fenkra (ok/parcial/nao), nota Fenkra,
# diferenças entre as ferramentas, chaves de fonte, ID de backlog (se há lacuna).

def e(id, mod, nome, faz, como, nomes, st, nota, dif, fontes, bl=None):
    return dict(id=id, modulo=mod, nome=nome, faz=faz, como=como,
                catia=nomes[0], sw=nomes[1], inv=nomes[2], fenkra=nomes[3],
                status=st, nota=nota, diferencas=dif, fontes=fontes, backlog=bl)

